import fs from 'node:fs';
import path from 'node:path';

const baseDir = path.resolve(process.cwd(), '.open-next/server-functions/default');
const handlerPath = path.join(baseDir, 'handler.mjs');

console.log('Pruning unused wasm from OpenNext bundle...');

if (fs.existsSync(handlerPath)) {
  let content = fs.readFileSync(handlerPath, 'utf8');
  const regex = /case"[^"]*(?:@prisma\/dev|@electric-sql|prisma\/build)[^"]*":return\(await import\("[^"]*"\)\)\.default;/g;
  const matches = content.match(regex);
  if (matches && matches.length > 0) {
    content = content.replace(regex, '');
    fs.writeFileSync(handlerPath, content, 'utf8');
    console.log(`Removed ${matches.length} unused wasm imports from handler.mjs`);
  }
}

const dirsToRemove = [
  path.join(baseDir, 'node_modules/@prisma/dev'),
  path.join(baseDir, 'node_modules/prisma'),
  path.join(baseDir, 'node_modules/@electric-sql'),
  path.join(baseDir, 'prisma'),
];

for (const dir of dirsToRemove) {
  if (fs.existsSync(dir)) {
    fs.rmSync(dir, { recursive: true, force: true });
    console.log(`Removed directory: ${dir}`);
  }
}

// Copy query_compiler_fast_bg.wasm to all route directories that import it
const wasmSrc = path.resolve(
  process.cwd(),
  'src/generated/client/internal/query_compiler_fast_bg.wasm'
);

if (fs.existsSync(wasmSrc)) {
  const possibleAppDirs = [
    path.join(baseDir, '.next/server/app'),
    path.join(baseDir, 'src/app'),
  ];
  let copyCount = 0;
  function copyWasmToRoutes(dir) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        copyWasmToRoutes(full);
      } else if (entry.name === 'page.js' || entry.name === 'route.js') {
        const targetWasm = path.join(dir, 'query_compiler_fast_bg.wasm');
        fs.copyFileSync(wasmSrc, targetWasm);
        copyCount++;
      }
    }
  }
  for (const appDir of possibleAppDirs) {
    if (fs.existsSync(appDir)) {
      copyWasmToRoutes(appDir);
    }
  }
  console.log(`Copied query_compiler_fast_bg.wasm to ${copyCount} route directories.`);
}

// Copy static/wasm if generated by Webpack
const nextWasmDir = path.resolve(process.cwd(), '.next/server/chunks/static/wasm');
if (fs.existsSync(nextWasmDir)) {
  const targetDir1 = path.join(baseDir, 'static/wasm');
  const targetDir2 = path.join(baseDir, '.next/server/chunks/static/wasm');
  fs.mkdirSync(targetDir1, { recursive: true });
  fs.mkdirSync(targetDir2, { recursive: true });
  for (const file of fs.readdirSync(nextWasmDir)) {
    fs.copyFileSync(path.join(nextWasmDir, file), path.join(targetDir1, file));
    fs.copyFileSync(path.join(nextWasmDir, file), path.join(targetDir2, file));
  }
  console.log('Copied static/wasm files to server-functions.');
}

console.log('Pruning and wasm setup complete.');
